    private function currentCash(Request $r, bool $lock=false): ?object {return app(\App\Services\CashService::class)->current($r,$lock);}
    
    private function promotionDiscount(object $promo, array $items, int $company, ?int $customer): float {
        $rules=json_decode($promo->rules ?: '{}',true);$lines=collect($items)->map(function($i)use($company){$p=DB::table('products')->where(['id'=>$i['product_id'],'company_id'=>$company])->firstOrFail();return ['product_id'=>$p->id,'category'=>$p->category,'brand'=>$p->brand,'quantity'=>(float)$i['quantity'],'unit_price'=>(float)$i['unit_price'],'total'=>(float)($i['line_total']??((float)$i['quantity']*(float)$i['unit_price']))];});
        $productIds=DB::table('promotion_product')->where('promotion_id',$promo->id)->pluck('product_id')->map(fn($x)=>(int)$x);
        $categories=DB::table('promotion_category as pc')->join('categories as c','c.id','=','pc.category_id')->where('pc.promotion_id',$promo->id)->pluck('c.name');
        $brands=DB::table('promotion_brand as pb')->join('brands as b','b.id','=','pb.brand_id')->where('pb.promotion_id',$promo->id)->pluck('b.name');
        $scoped=$productIds->isNotEmpty()||$categories->isNotEmpty()||$brands->isNotEmpty();
        $eligible=$lines->filter(fn($l)=>!$scoped||$productIds->contains($l['product_id'])||$categories->contains($l['category'])||$brands->contains($l['brand']));
        $eligibleSubtotal=(float)$eligible->sum('total');$eligibleQuantity=(float)$eligible->sum('quantity');$saleSubtotal=(float)$lines->sum('total');
        abort_if($eligible->isEmpty(),422,'La promoción no aplica a los productos seleccionados');
        abort_if($saleSubtotal<(float)($rules['minimum_amount']??0),422,'No se alcanzó el monto mínimo de la promoción');
        abort_if($eligibleQuantity<(float)($rules['minimum_quantity']??0),422,'No se alcanzó la cantidad mínima de la promoción');
        if($customer&&!empty($rules['max_uses_per_customer'])){$uses=DB::table('promotion_usages')->where(['promotion_id'=>$promo->id,'customer_id'=>$customer])->count();abort_if($uses>=(int)$rules['max_uses_per_customer'],422,'El cliente ya alcanzó el límite de uso de la promoción');}
        return round(match($promo->type){
            'percentage'=>$eligibleSubtotal*(float)$promo->value/100,
            'fixed'=>min($eligibleSubtotal,(float)$promo->value),
            'buy_x_get_y'=>$eligible->sum(function($l)use($rules){$buy=max(1,(int)($rules['buy_quantity']??1));$get=max(1,(int)($rules['get_quantity']??1));return floor($l['quantity']/($buy+$get))*$get*$l['unit_price'];}),
            'combo'=>max(0,$eligibleSubtotal-(float)($rules['combo_price']??$promo->value)),
            default=>0
        },2);
    }

    public function dashboard(Request $r) {
        [$c,$b]=$this->ctx($r); $today=now()->toDateString();
        $sales=DB::table('sales')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'paid'])->whereDate('created_at',$today);
        $cash=DB::table('cash_sessions')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'open'])->latest()->first();
        $critical=DB::table('stocks as s')->join('products as p','p.id','=','s.product_id')->where('s.company_id',$c)->where('p.status','active')->whereColumn('s.quantity','<=','p.minimum_stock')->distinct()->count('p.id');
        return response()->json(['success'=>true,'data'=>['sales_today'=>(float)$sales->sum('total'),'sales_count'=>$sales->count(),'critical_stock'=>$critical,'cash_session'=>$cash,'recent_sales'=>DB::table('sales')->where('company_id',$c)->latest()->limit(5)->get()]]);
    }
    public function products(Request $r) {
        [$c,$b]=$this->ctx($r); $w=$this->branchWarehouse($c,$b);
        $rows=DB::table('products as p')->leftJoin('stocks as s',fn($j)=>$j->on('s.product_id','=','p.id')->where('s.warehouse_id',$w->id))->where('p.company_id',$c)
            ->select('p.*',DB::raw('COALESCE(s.quantity,0) as stock'))->orderBy('p.name')->get();
        $links=DB::table('product_suppliers')->where(['company_id'=>$c,'status'=>'active'])->get()->groupBy('product_id');
        $presentations=app(\App\Services\ProductPresentationService::class)->forCompany($c);
        foreach($rows as $row){$row->supplier_products=$links->get($row->id,collect())->values();$row->presentations=$presentations->get($row->id,collect())->values();}
        return response()->json(['success'=>true,'data'=>$rows]);
    }
