            if($id){$before=DB::table('products')->where(['id'=>$id,'company_id'=>$c])->firstOrFail();if($before->unit_type!==$data['unit_type']&&app(\App\Services\ProductPresentationService::class)->hasHistory($id))abort(422,'No se puede cambiar la unidad base de un producto con stock o movimientos: las cantidades registradas quedarían mal interpretadas. Crea un producto nuevo con la unidad correcta.');DB::table('products')->where(['id'=>$id,'company_id'=>$c])->update($payload);if((float)$before->sale_price!==(float)$data['sale_price'])DB::table('price_history')->insert(['company_id'=>$c,'product_id'=>$id,'user_id'=>$r->user()->id,'previous_price'=>$before->sale_price,'new_price'=>$data['sale_price'],'reason'=>'Edición de producto','created_at'=>now(),'updated_at'=>now()]);if((float)$before->average_cost!==(float)($data['average_cost']??0))DB::table('cost_history')->insert(['company_id'=>$c,'product_id'=>$id,'user_id'=>$r->user()->id,'previous_cost'=>$before->average_cost,'new_cost'=>$data['average_cost']??0,'source'=>'Edición manual','created_at'=>now(),'updated_at'=>now()]);}
