            if(!$id || array_key_exists('stock',$data) && $data['stock']!==null)$stockPayload['quantity']=$data['stock']??0;
            if(!DB::table('stocks')->where(['warehouse_id'=>$w->id,'product_id'=>$id])->exists()){$stockPayload['quantity']=$stockPayload['quantity']??0;$stockPayload['created_at']=now();}
            $isNew=!DB::table('stocks')->where(['warehouse_id'=>$w->id,'product_id'=>$id])->exists();DB::table('stocks')->updateOrInsert(['warehouse_id'=>$w->id,'product_id'=>$id],$stockPayload);if($isNew&&(float)($stockPayload['quantity']??0)>0)DB::table('inventory_movements')->insert(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'warehouse_id'=>$w->id,'product_id'=>$id,'user_id'=>$r->user()->id,'type'=>'initial_stock','quantity'=>$stockPayload['quantity'],'historical_unit_cost'=>$data['average_cost']??0,'previous_stock'=>0,'new_stock'=>$stockPayload['quantity'],'document_type'=>'product','document_id'=>$id,'document_number'=>$data['sku'],'created_at'=>now(),'updated_at'=>now()]);
            if(array_key_exists('presentations',$data))app(\App\Services\ProductPresentationService::class)->sync($c,$id,$data['unit_type'],$data['presentations']);
            $this->recordAudit($r,$id?'product.saved':'product.created','product',$id,$payload);
