    public function customers(Request $r) { [$c]=$this->ctx($r); return response()->json(['success'=>true,'data'=>DB::table('customers')->where('company_id',$c)->where('status','active')->orderBy('name')->get()]); }
    public function customerDocument(Request $r) {
        [$c]=$this->ctx($r);
        $d=$r->validate(['document_number'=>'required|digits_between:8,11']);
        $number=$d['document_number'];
        $local=DB::table('customers')->where(['company_id'=>$c,'document_number'=>$number])->first();
        if($local)return response()->json(['success'=>true,'data'=>['source'=>'local','customer'=>$local]]);
        $token=config('services.peru_document.token');
        if(!$token)return response()->json(['success'=>true,'data'=>['source'=>'manual','customer'=>null,'message'=>'Documento no registrado. Complete los datos del cliente.']]);
        $type=strlen($number)===11?'sunat/ruc':'reniec/dni';
        $response=Http::withToken($token)->acceptJson()->timeout(15)->get("https://api.apis.net.pe/v2/{$type}",['numero'=>$number]);
        abort_unless($response->successful(),422,'No fue posible consultar el documento en este momento');
        $json=$response->json();
        $name=$json['razonSocial']??$json['nombre']??trim(implode(' ',array_filter([$json['nombres']??null,$json['apellidoPaterno']??null,$json['apellidoMaterno']??null])));
        return response()->json(['success'=>true,'data'=>['source'=>'external','customer'=>['document_type'=>strlen($number)===11?'RUC':'DNI','document_number'=>$number,'name'=>$name,'address'=>$json['direccion']??null]]]);
    }
