    public function createPurchase(Request $r, ProductSupplierService $supplierService, \App\Services\InventoryCostService $costs) {
        [$c,$b,$u]=$this->ctx($r); $d=$r->validate(['supplier_id'=>['nullable','integer',Rule::exists('suppliers','id')->where(fn($q)=>$q->where(['company_id'=>$c,'status'=>'active']))],'invoice_number'=>'nullable|string|max:100','document_type'=>'nullable|in:quick,invoice,receipt,guide','items'=>'required|array|min:1','items.*.product_id'=>'required|integer','items.*.quantity'=>'required|numeric|min:0.001','items.*.unit_cost'=>'required|numeric|min:0','items.*.lot_number'=>'nullable|string|max:60','items.*.expires_at'=>'nullable|date','tax'=>'nullable|numeric|min:0','freight'=>'nullable|numeric|min:0','perception'=>'nullable|numeric|min:0','other_costs'=>'nullable|numeric|min:0']);
        return DB::transaction(function() use($r,$c,$b,$u,$d,$supplierService,$costs) {
            $w=$this->branchWarehouse($c,$b);
            $subtotal=collect($d['items'])->sum(fn($i)=>$i['quantity']*$i['unit_cost']);
            $effective=$costs->effectiveCosts($d['items'],(float)(($d['freight']??0)+($d['other_costs']??0)));
            $number='C001-'.str_pad((string)(DB::table('purchases')->where('company_id',$c)->count()+1),6,'0',STR_PAD_LEFT);
            $purchaseId=DB::table('purchases')->insertGetId(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'supplier_id'=>$d['supplier_id']??null,'user_id'=>$u,'number'=>$number,'invoice_number'=>$d['invoice_number']??null,'document_type'=>$d['document_type']??'quick','subtotal'=>$subtotal,'tax'=>$d['tax']??0,'freight'=>$d['freight']??0,'perception'=>$d['perception']??0,'other_costs'=>$d['other_costs']??0,'total'=>$subtotal+($d['tax']??0)+($d['freight']??0)+($d['perception']??0)+($d['other_costs']??0),'status'=>'confirmed','created_at'=>now(),'updated_at'=>now()]);
            foreach($d['items'] as $k=>$i){
                $p=DB::table('products')->where(['id'=>$i['product_id'],'company_id'=>$c])->lockForUpdate()->firstOrFail();
                $s=DB::table('stocks')->where(['warehouse_id'=>$w->id,'product_id'=>$p->id])->lockForUpdate()->first();
                $before=(float)($s->quantity??0); $new=$before+$i['quantity'];
                DB::table('purchase_details')->insert(['purchase_id'=>$purchaseId,'product_id'=>$p->id,'quantity'=>$i['quantity'],'unit_cost'=>$i['unit_cost'],'effective_unit_cost'=>$effective[$k],'total'=>$i['quantity']*$i['unit_cost'],'lot_number'=>($i['lot_number']??null)?:null,'expires_at'=>$i['expires_at']??null,'created_at'=>now(),'updated_at'=>now()]);
                $costs->receive($c,$p->id,(float)$i['quantity'],$effective[$k],$u,"Compra {$number}");
                DB::table('stocks')->updateOrInsert(['warehouse_id'=>$w->id,'product_id'=>$p->id],['company_id'=>$c,'branch_id'=>$w->branch_id,'quantity'=>$new,'created_at'=>now(),'updated_at'=>now()]);
                if(!empty($i['lot_number']))app(\App\Services\LotService::class)->receive($c,$w->id,$p->id,(float)$i['quantity'],$i['lot_number'],$i['expires_at']??null,$effective[$k],'purchase',$purchaseId);
                DB::table('inventory_movements')->insert(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'warehouse_id'=>$w->id,'product_id'=>$p->id,'user_id'=>$u,'type'=>'purchase_in','quantity'=>$i['quantity'],'historical_unit_cost'=>$effective[$k],'previous_stock'=>$before,'new_stock'=>$new,'document_type'=>'purchase','document_id'=>$purchaseId,'document_number'=>$number,'created_at'=>now(),'updated_at'=>now()]);
            }
            $purchase=DB::table('purchases')->where('id',$purchaseId)->first();
            $supplierService->syncConfirmedPurchase($c,$purchase,DB::table('purchase_details')->where('purchase_id',$purchaseId)->get());
            $this->recordAudit($r,'purchase.confirmed','purchase',$purchaseId,['number'=>$number]);
            return response()->json(['success'=>true,'message'=>'Compra confirmada y stock actualizado','data'=>['id'=>$purchaseId,'number'=>$number]],201);
        });
    }
