            foreach($d['items'] as $i){ $p=DB::table('products')->where(['id'=>$i['product_id'],'company_id'=>$c])->firstOrFail(); if($i['entry_mode']!=='presentation'&&$i['unit_price']<$p->minimum_price) abort(422,"Precio menor al mínimo para {$p->name}"); if(!$p->allow_decimal_quantity && fmod((float)$i['quantity'],1.0)!==0.0) abort(422,"{$p->name} solo permite unidades enteras");
                $s=DB::table('stocks')->where(['warehouse_id'=>$w->id,'product_id'=>$p->id])->lockForUpdate()->first(); $before=(float)($s->quantity??0); if($before<$i['quantity']) abort(422,"Stock insuficiente para {$p->name}"); $new=$before-$i['quantity'];
                DB::table('sale_details')->insert(['sale_id'=>$saleId,'product_id'=>$p->id,'product_name'=>$p->name,'quantity'=>$i['quantity'],'unit_price'=>$i['unit_price'],'presentation_id'=>$i['presentation']['id']??null,'presentation_name'=>$i['presentation']['name']??null,'presentation_quantity'=>$i['presentation']['quantity']??null,'presentation_factor'=>$i['presentation']['factor']??null,'historical_unit_cost'=>$p->average_cost,'discount'=>$i['line_discount'],'total'=>$i['line_total'],'entry_mode'=>$i['entry_mode'],'created_at'=>now(),'updated_at'=>now()]); DB::table('stocks')->where('id',$s->id)->update(['quantity'=>$new,'updated_at'=>now()]);app(\App\Services\LotService::class)->consume($c,$w->id,$p->id,(float)$i['quantity'],'sale',$saleId);
                DB::table('inventory_movements')->insert(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'warehouse_id'=>$w->id,'product_id'=>$p->id,'user_id'=>$u,'type'=>'sale_out','quantity'=>-$i['quantity'],'historical_unit_cost'=>$p->average_cost,'previous_stock'=>$before,'new_stock'=>$new,'document_type'=>'sale','document_id'=>$saleId,'document_number'=>$number,'created_at'=>now(),'updated_at'=>now()]);
            } foreach($d['payments'] as $p){ DB::table('sale_payments')->insert(['sale_id'=>$saleId,'method'=>$p['method'],'amount'=>$p['amount'],'reference'=>$p['reference']??null,'created_at'=>now(),'updated_at'=>now()]); if($p['method']==='cash') DB::table('cash_movements')->insert(['cash_session_id'=>$cash->id,'type'=>'sale','amount'=>$p['amount'],'description'=>"Venta {$number}",'reference'=>$number,'user_id'=>$u,'created_at'=>now(),'updated_at'=>now()]); }
            $overrides=collect($d['items'])->where('price_overridden',true)->map(fn($i)=>['product_id'=>$i['product_id'],'catalog_price'=>$i['catalog_price'],'applied_price'=>$i['unit_price']])->values();if($overrides->isNotEmpty())$this->recordAudit($r,'sale.price_overridden','sale',$saleId,['reason'=>$d['price_override_reason'],'items'=>$overrides]);if($lineDiscounts>0||(float)($d['discount']??0)>0)$this->recordAudit($r,'sale.discount_applied','sale',$saleId,['reason'=>$d['discount_reason']??null,'sale_discount'=>(float)($d['discount']??0),'lines'=>collect($d['items'])->where('line_discount','>',0)->map(fn($i)=>['product_id'=>$i['product_id'],'discount'=>$i['line_discount']])->values()]);$this->recordAudit($r,'sale.completed','sale',$saleId,['number'=>$number,'total'=>$total]); return response()->json(['success'=>true,'message'=>'Venta registrada','data'=>['id'=>$saleId,'number'=>$number,'total'=>$total]],201);
        });
    }
    public function cashStatus(Request $r) { $s=$this->currentCash($r); if($s){$s->movements=DB::table('cash_movements')->where('cash_session_id',$s->id)->latest()->get();$s->expected_amount=app(\App\Services\CashService::class)->expected($s->id);} return response()->json(['success'=>true,'data'=>$s]); }
    public function openCash(Request $r) { [$c,$b,$u]=$this->ctx($r);$d=$r->validate(['opening_amount'=>'required|numeric|min:0','cash_register_id'=>'required|integer']);DB::table('cash_registers')->where(['id'=>$d['cash_register_id'],'company_id'=>$c,'branch_id'=>$b,'status'=>'active'])->firstOrFail();if(DB::table('cash_sessions')->where(['cash_register_id'=>$d['cash_register_id'],'status'=>'open'])->exists())return response()->json(['success'=>false,'message'=>'Esa caja física ya tiene un turno abierto'],422);$id=DB::table('cash_sessions')->insertGetId(['company_id'=>$c,'branch_id'=>$b,'cash_register_id'=>$d['cash_register_id'],'user_id'=>$u,'opening_amount'=>$d['opening_amount'],'status'=>'open','opened_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$r->user()->update(['cash_session_id'=>$id]);DB::table('cash_movements')->insert(['cash_session_id'=>$id,'type'=>'opening','amount'=>$d['opening_amount'],'description'=>'Apertura de caja','user_id'=>$u,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Caja abierta','data'=>['id'=>$id]]); }
    public function closeCash(Request $r) { [$c,$b,$u]=$this->ctx($r); $d=$r->validate(['counted_amount'=>'required|numeric|min:0','denominations'=>'nullable|array','notes'=>'nullable']); return DB::transaction(function()use($r,$u,$d){$s=$this->currentCash($r,true);abort_unless($s,404,'No hay una caja seleccionada abierta');$expected=app(\App\Services\CashService::class)->expected($s->id); DB::table('cash_sessions')->where('id',$s->id)->update(['expected_amount'=>$expected,'counted_amount'=>$d['counted_amount'],'difference'=>$d['counted_amount']-$expected,'status'=>'closed','closed_at'=>now(),'updated_at'=>now()]);$r->user()->update(['cash_session_id'=>null]);DB::table('cash_audits')->insert(['cash_session_id'=>$s->id,'user_id'=>$u,'type'=>'final','expected_amount'=>$expected,'counted_amount'=>$d['counted_amount'],'difference'=>$d['counted_amount']-$expected,'denominations'=>isset($d['denominations'])?json_encode($d['denominations']):null,'notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]); return response()->json(['success'=>true,'message'=>'Caja cerrada','data'=>['expected'=>$expected,'counted'=>$d['counted_amount'],'difference'=>$d['counted_amount']-$expected]]);}); }
    public function expenses(Request $r) { [$c,$b]=$this->ctx($r); return response()->json(['success'=>true,'data'=>DB::table('expenses')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'active'])->latest('expense_date')->get()]); }
    public function createExpense(Request $r) { [$c,$b,$u]=$this->ctx($r); $d=$r->validate(['category'=>'required','description'=>'required','amount'=>'required|numeric|min:0.01','expense_date'=>'required|date']); $cash=DB::table('cash_sessions')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'open'])->first(); $id=DB::table('expenses')->insertGetId($d+['company_id'=>$c,'branch_id'=>$b,'user_id'=>$u,'status'=>'active','created_at'=>now(),'updated_at'=>now()]); if($cash) DB::table('cash_movements')->insert(['cash_session_id'=>$cash->id,'type'=>'expense','amount'=>$d['amount'],'description'=>$d['description'],'reference'=>"G-{$id}",'user_id'=>$u,'created_at'=>now(),'updated_at'=>now()]); return response()->json(['success'=>true,'message'=>'Gasto registrado','data'=>['id'=>$id]]); }
    public function kardex(Request $r) { [$c,$b]=$this->ctx($r); $q=DB::table('inventory_movements as m')->join('products as p','p.id','=','m.product_id')->leftJoin('warehouses as w','w.id','=','m.warehouse_id')->where(['m.company_id'=>$c,'m.branch_id'=>$b])->select('m.*','p.name as product_name','p.sku','p.category','p.brand','w.name as warehouse_name'); if($r->product_id)$q->where('m.product_id',$r->product_id); return response()->json(['success'=>true,'data'=>$q->latest('m.created_at')->orderByDesc('m.id')->limit(500)->get()]); }
}
